import itertools


def squash(s: str) -> str:
    res = []
    for c, group in itertools.groupby(s):
        count = sum(1 for _ in group)
        esc_c = f"\\{c}" if c.isdigit() or c == "\\" else c
        if count >= 3:
            res.append(f"{count}{esc_c}")
        else:
            res.append(esc_c * count)
    return "".join(res)
